    [Fact]
    public void ExtendedAssemblyInfoGenerationPreservesNoOpBuildTimestamps()
    {
        var targetsPath = FindRepoPath(
            "eng",
            "WpfArcadeSdk",
            "tools",
            "ExtendedAssemblyInfo.targets");
        var targets = XDocument.Load(targetsPath);
        var generationTarget = Assert.Single(
