    [Theory]
    [InlineData("src/Microsoft.DotNet.Wpf/src/System.Xaml/System.Xaml.csproj")]
    [InlineData("src/Microsoft.DotNet.Wpf/src/PresentationBuildTasks/PresentationBuildTasks.csproj")]
    [InlineData("src/Microsoft.DotNet.Wpf/src/PresentationFramework/PresentationFramework.csproj")]
    [InlineData("src/Microsoft.DotNet.Wpf/src/PresentationUI/PresentationUI.csproj")]
    [InlineData("src/Microsoft.DotNet.Wpf/src/Themes/PresentationFramework.Fluent/PresentationFramework.Fluent.csproj")]
    [InlineData("src/Microsoft.DotNet.Wpf/src/System.Windows.Controls.Ribbon/System.Windows.Controls.Ribbon.csproj")]
    public void ManagedWpfSubsystemProjectsDoNotReferenceProGpuBridge(string relativeProjectPath)
    {
        var projectPath = FindRepoPath(relativeProjectPath.Split('/'));
        var project = File.ReadAllText(projectPath);
        var projectWithoutInteropContract = project
            .Replace(@"$(WpfSourceDir)..\..\..\external\ProGPU\src\ProGPU.Wpf.Interop\ProGPU.Wpf.Interop.csproj", string.Empty, StringComparison.Ordinal)
            .Replace(@"..\..\..\..\external\ProGPU\src\ProGPU.Wpf.Interop\ProGPU.Wpf.Interop.csproj", string.Empty, StringComparison.Ordinal);

        Assert.DoesNotContain("ProGPU.Wpf", projectWithoutInteropContract, StringComparison.Ordinal);
        Assert.DoesNotContain(@"external\ProGPU", projectWithoutInteropContract, StringComparison.Ordinal);
        Assert.DoesNotContain("ProGPU.Scene", projectWithoutInteropContract, StringComparison.Ordinal);
    }

    [Fact]
